//@name dusk_update_size_12mb
//@display-name Dusk Update Size Probe 1.2 MiB
//@api 3.0
//@version 0.2.0
//@update-url https://raw.githubusercontent.com/Pyser08/Dusk-Atelier/test/update-size-probe/tests/update-size-probe/hosted/probe-12mb.js
//@link https://github.com/Pyser08/Dusk-Atelier/tree/test/update-size-probe/tests/update-size-probe
(async () => {
  const api = globalThis.risuai ?? globalThis.Risuai;
  if (!api) return;
  const label = "Dusk Update Size Probe 1.2 MiB v0.2.0";
  try {
    await api.registerSetting(label, async () => {
      console.log('[Dusk Update Size Probe] ' + label + ' loaded');
    }, '🧪', 'text');
  } catch (e) {
    console.log('[Dusk Update Size Probe] ' + label + ' registerSetting failed', e);
  }
  console.log('[Dusk Update Size Probe] loaded: ' + label);
})();

